
(async()=>{
  if(window.__V90_DODGE_ROLL)return;
  window.__V90_DODGE_ROLL=true;

  const ROLL_GZ="";
  const SOURCE={"file":"Sprinting Forward Roll.fbx","raw_bytes":1855488,"gzip_bytes":1287892,"sha256":"9a6ea69b8dbdbd244571b0b2ee1845742d9b4fb586949cfa152943ea1bcdf3fc"};
  const sleep=ms=>new Promise(r=>setTimeout(r,ms));
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  const smooth=t=>{t=clamp(t,0,1);return t*t*(3-2*t)};

  async function gunzipB64(s){
    const bin=atob(s);
    const raw=new Uint8Array(bin.length);
    for(let i=0;i<bin.length;i++)raw[i]=bin.charCodeAt(i);

    if(typeof DecompressionStream!=="undefined"){
      const ds=new DecompressionStream("gzip");
      return await new Response(new Blob([raw]).stream().pipeThrough(ds)).arrayBuffer();
    }

    if(window.__FFLATE_GUNZIP_SYNC){
      const out=window.__FFLATE_GUNZIP_SYNC(raw);
      return out.buffer.slice(out.byteOffset,out.byteOffset+out.byteLength);
    }

    throw new Error("Sem descompressor gzip para o rolamento.");
  }

  async function waitGame(){
    for(let i=0;i<1200;i++){
      const g=window.gameReview;
      if(
        g?.player && g?.camera && g?.groundY && g?.collides && g?.keys &&
        g?.trueFirstPerson?.model && g?.trueFirstPerson?.visibleRoot && g?.trueFirstPerson?.eyeSocket &&
        g?.trueFirstPerson?.bones?.lHand && g?.trueFirstPerson?.bones?.rHand &&
        window.__FBX_MODULE && window.__THREE_MODULE &&
        window.gameZombie?.hurtPlayer && typeof window.__updateAnimatedAvatar==="function"
      ) return g;
      await sleep(20);
    }
    throw new Error("Jogo/rig não ficaram disponíveis para o rolamento.");
  }

  const game=await waitGame();
  const THREE=window.__THREE_MODULE;
  const {FBXLoader}=window.__FBX_MODULE;
  const tfp=game.trueFirstPerson;
  const player=game.player;
  const keys=game.keys;
  const status=document.getElementById("status");

  const CFG={
    distance:5.65,
    animationSpeed:1.0,
    iframeStart:.16,
    iframeEnd:.67,
    cooldownMs:260,
    cameraFollowsEyes:true,
    // Distâncias de esquiva: preserva 5,65u do rolamento frontal original.
    sideDistance:5.05,
    backDistance:4.55,
    // A orientação lateral acontece durante a cambalhota, sem teleporte de yaw.
    sideTurnIn:.18,
    sideTurnOutStart:.66,
    sideTurnOutEnd:.97
  };

  const parsed=new FBXLoader().parse(await gunzipB64(ROLL_GZ),"");
  if(!parsed.animations?.length)throw new Error("Sprinting Forward Roll.fbx não contém animação.");

  const rollClip=parsed.animations[0].clone();
  rollClip.name="V90_Sprinting_Forward_Roll_LONG_FULL_BODY_EYE_CAMERA";
  rollClip.tracks=rollClip.tracks.filter(track=>{
    const n=track.name;
    if(/\.position$/i.test(n))return false;
    if(/\.scale$/i.test(n))return false;
    if(/\.quaternion$/i.test(n)){
      // Fingers remain under the current grip system so held equipment does not detach.
      if(/Hand(Thumb|Index|Middle|Ring|Pinky)/i.test(n))return false;
      return true;
    }
    return false;
  });
  rollClip.resetDuration();
  if(!rollClip.tracks.length)throw new Error("O FBX de rolamento não possui tracks compatíveis com o rig atual.");

  const mixer=new THREE.AnimationMixer(tfp.model);
  const action=mixer.clipAction(rollClip,tfp.model);
  action.enabled=true;
  action.setLoop(THREE.LoopOnce,1);
  action.clampWhenFinished=true;
  action.setEffectiveWeight(1);
  action.setEffectiveTimeScale(CFG.animationSpeed);

  let active=false;
  let progress=0;
  let lastCurve=0;
  let lastGrounded=true;
  let cooldownUntil=0;
  let lastFrame=performance.now();
  let rollYaw=player.bodyYaw??player.yaw??0;
  let rollFacingYaw=rollYaw;
  let rollTurnDelta=0;
  let dodgeKind="forward";
  let rollDirX=0;
  let rollDirZ=-1;
  let rollSerial=0;

  const handWorldQ=new THREE.Quaternion();
  const socketQuat=new THREE.Quaternion();
  const socketPos=new THREE.Vector3();
  const torchPos=new THREE.Vector3();
  const bodyYawQ=new THREE.Quaternion();
  const yAxis=new THREE.Vector3(0,1,0);
  const torchOffset=new THREE.Vector3(0,.06*.65,0);

  // True POV roll camera: the camera is treated as the character's eyes.
  // We preserve the camera-vs-eye alignment that exists at the instant the roll
  // starts, then apply the animated eye socket's full world transform every frame.
  // This means pitch, yaw AND roll follow the head through the somersault.
  const eyeWorldPos=new THREE.Vector3();
  const eyeWorldQ=new THREE.Quaternion();
  const rollStartEyeQ=new THREE.Quaternion();
  const rollStartCameraQ=new THREE.Quaternion();
  const eyeToCameraQ=new THREE.Quaternion();

  function blocked(){
    return !!(
      window.gameAttack?.active ||
      window.gameCraft?.active ||
      window.gameHammerCraft?.active ||
      window.gamePlayerHit?.active ||
      window.gameLogPlacement?.placing ||
      window.gameShieldCraft?.positioning ||
      document.body.classList.contains("crafting-active")
    );
  }

  function inputVector(){
    let x=Number(game.stick?.x)||0;
    let y=Number(game.stick?.y)||0;
    if(keys.has("KeyA")||keys.has("ArrowLeft"))x-=1;
    if(keys.has("KeyD")||keys.has("ArrowRight"))x+=1;
    if(keys.has("KeyW")||keys.has("ArrowUp"))y-=1;
    if(keys.has("KeyS")||keys.has("ArrowDown"))y+=1;
    const l=Math.hypot(x,y);
    if(l>1){x/=l;y/=l;}
    return {x,y,l};
  }

  // PC: segure A / D / S e aperte V. V e V+W mantêm o giro frontal original.
  // Uma mesma FBX real de cambalhota dirige as laterais; ao recuar usamos
  // a FBX em ordem temporal inversa, criando uma cambalhota para trás de verdade.
  // NENHUMA pose de 'deitar no chão' é gerada ou usada como esquiva.
  function captureDirection(forced){
    const m=inputVector();
    rollFacingYaw=player.bodyYaw??player.yaw??0;
    const sy=Math.sin(rollFacingYaw), cy=Math.cos(rollFacingYaw);
    const ax=Math.abs(m.x), ay=Math.abs(m.y);
    if(["left","right","backward","forward"].includes(forced)){
      dodgeKind=forced;
    }else if(ax>.15 && ax>=ay*.75){
      dodgeKind=m.x<0?"left":"right";
    }else if(m.y>.15){
      dodgeKind="backward";
    }else{
      dodgeKind="forward";
    }

    if(dodgeKind==="left"){
      rollDirX=-cy; rollDirZ=sy;
    }else if(dodgeKind==="right"){
      rollDirX=cy; rollDirZ=-sy;
    }else if(dodgeKind==="backward"){
      rollDirX=sy; rollDirZ=cy;
    }else{
      rollDirX=-sy; rollDirZ=-cy;
    }

    // Giro lateral suave para entrar e sair da cambalhota sobre o ombro.
    // No recuo NÃO viramos 180 graus: a FBX roda ao contrário, preservando
    // o olhar / orientação de combate e revertendo o sentido do giro.
    const targetYaw=(dodgeKind==="left"||dodgeKind==="right")
      ?Math.atan2(-rollDirX,-rollDirZ):rollFacingYaw;
    rollTurnDelta=Math.atan2(
      Math.sin(targetYaw-rollFacingYaw),Math.cos(targetYaw-rollFacingYaw)
    );
    rollYaw=rollFacingYaw;
  }

  function updateDodgeFacing(){
    if(dodgeKind!=="left"&&dodgeKind!=="right"){
      rollYaw=rollFacingYaw;
      return;
    }
    const intoRoll=smooth(progress/CFG.sideTurnIn);
    const outOfRoll=1-smooth(
      (progress-CFG.sideTurnOutStart)/(CFG.sideTurnOutEnd-CFG.sideTurnOutStart)
    );
    rollYaw=rollFacingYaw+rollTurnDelta*intoRoll*outOfRoll;
  }

  function moveDistance(amount){
    if(!(amount>0))return;
    const dx=rollDirX*amount;
    const dz=rollDirZ*amount;
    const nx=player.x+dx;
    if(!game.collides(nx,player.z))player.x=nx;
    const nz=player.z+dz;
    if(!game.collides(player.x,nz))player.z=nz;
  }

  function isInvulnerable(){
    return active && progress>=CFG.iframeStart && progress<=CFG.iframeEnd;
  }

  function syncRightHand(){
    const prev=window.__shieldFullBodyPose;
    window.__shieldFullBodyPose=true;
    try{window.gameRightHand?.sync?.();}
    finally{window.__shieldFullBodyPose=prev;}
  }

  function syncShield(){
    if(!window.gameShield?.equipped || !window.gameShield?.object)return;
    const hand=tfp.bones.lHand;
    const socket=window.gameShieldAnimations?.shieldSocket;
    if(!hand || !socket?.ready)return;

    tfp.visibleRoot.updateMatrixWorld(true);
    hand.updateWorldMatrix(true,false);
    socketPos.fromArray(socket.localPosition);
    hand.localToWorld(socketPos);
    hand.getWorldQuaternion(handWorldQ);
    socketQuat.fromArray(socket.localQuaternion);

    const obj=window.gameShield.object;
    obj.position.copy(socketPos);
    obj.quaternion.copy(handWorldQ).multiply(socketQuat);
    obj.visible=true;
  }

  function syncTorch(){
    if(!game.torchRoot || !game.isEquipped?.() || !tfp.socket)return;
    tfp.visibleRoot.updateMatrixWorld(true);
    tfp.socket.getWorldPosition(torchPos);
    bodyYawQ.setFromAxisAngle(yAxis,rollYaw);
    game.torchRoot.position.copy(torchPos).sub(torchOffset.clone().applyQuaternion(bodyYawQ));
  }

  function syncBodyAndCamera(args){
    // The world controller owns the actual player position. Root translation from
    // Mixamo stays disabled so collision remains authoritative, but EVERY bone
    // rotation from the roll still drives the character, including the head.
    tfp.visibleRoot.position.x=player.x;
    tfp.visibleRoot.position.z=player.z;
    updateDodgeFacing();
    tfp.visibleRoot.rotation.y=rollYaw;
    tfp.visibleRoot.updateMatrixWorld(true);

    syncRightHand();
    syncShield();
    syncTorch();

    // TRUE FIRST PERSON: the camera is literally attached to the anatomical eye
    // socket. No horizon stabilization and no artificial camera dip. During the
    // forward roll the view goes down, upside-down and back upright exactly as
    // the animated head/eyes do. eyeToCameraQ only preserves the model/camera
    // axis alignment and the view offset that existed when the dodge started.
    tfp.visibleRoot.updateMatrixWorld(true);
    tfp.eyeSocket.getWorldPosition(eyeWorldPos);
    tfp.eyeSocket.getWorldQuaternion(eyeWorldQ);
    game.camera.position.copy(eyeWorldPos);
    game.camera.quaternion.copy(eyeWorldQ).multiply(eyeToCameraQ);
    game.camera.updateMatrixWorld(true);
    if(tfp.state)tfp.state.eyeError=game.camera.position.distanceTo(eyeWorldPos);
  }

  function finishRoll(reason="done"){
    if(!active)return;
    active=false;
    progress=1;
    action.stop();
    mixer.stopAllAction();
    // O modelo volta a olhar para a frente após a esquiva lateral.
    // Nunca modifica player.yaw nem os controles de câmera do jogo.
    if(dodgeKind!=="forward")tfp.visibleRoot.rotation.y=rollFacingYaw;
    cooldownUntil=performance.now()+CFG.cooldownMs;
    document.body.classList.remove("player-rolling");
    window.gameRightHand?.sync?.();
    if(reason==="hit" && status)status.textContent="Rolamento interrompido pelo golpe";
  }

  function startRoll(requestedKind){
    const now=performance.now();
    if(active || now<cooldownUntil || !lastGrounded || blocked())return false;

    // Capture the exact current eye/camera relationship BEFORE the body is
    // reoriented for the dodge. This avoids a model-axis snap on the first frame
    // while still allowing the whole POV to tumble with the animated head.
    tfp.visibleRoot.updateMatrixWorld(true);
    tfp.eyeSocket.getWorldQuaternion(rollStartEyeQ);
    game.camera.getWorldQuaternion(rollStartCameraQ);
    eyeToCameraQ.copy(rollStartEyeQ).invert().multiply(rollStartCameraQ);

    captureDirection(requestedKind);
    window.gameShield?.setBlocking?.(false);

    active=true;
    progress=0;
    lastCurve=0;
    rollSerial++;
    document.body.classList.add("player-rolling");

    action.stop();
    action.reset();
    action.enabled=true;
    action.setEffectiveWeight(1);
    action.setLoop(THREE.LoopOnce,1);
    action.clampWhenFinished=true;
    // A marcha inversa da FBX frontal produz rolamento traseiro, sem
    // precisar de arquivo de terceiros ou interferir na esquiva para frente.
    const reverse=dodgeKind==="backward";
    action.time=reverse?Math.max(0,rollClip.duration-.00001):0;
    action.setEffectiveTimeScale((reverse?-1:1)*CFG.animationSpeed);
    action.play();
    lastFrame=now;

    const kindText={forward:"frente",left:"esquerda",right:"direita",backward:"trás"};
    if(status)status.textContent=`Cambalhota para ${kindText[dodgeKind]} • câmera nos olhos • i-frames no meio`;
    return true;
  }

  // I-frames are applied at the single health gateway used by zombies, bosses,
  // arrows and the other enemy systems. Attacks still happen visually; damage is
  // simply ignored during the invulnerability window of the dodge.
  const originalHurtPlayer=window.gameZombie.hurtPlayer.bind(window.gameZombie);
  window.gameZombie.hurtPlayer=(...args)=>{
    if(isInvulnerable()){
      if(status)status.textContent="Esquiva perfeita • ataque evitado";
      window.dispatchEvent(new CustomEvent("game:roll-dodged",{
        detail:{source:args[1]||"ataque",progress}
      }));
      return false;
    }
    return originalHurtPlayer(...args);
  };

  window.addEventListener("game:player-damaged",()=>{
    if(active && !isInvulnerable())finishRoll("hit");
  });

  const previousUpdate=window.__updateAnimatedAvatar;
  window.__updateAnimatedAvatar=function(...args){
    previousUpdate?.apply(this,args);
    lastGrounded=args[4]!==false;

    const now=performance.now();
    const dt=Math.min(.05,Math.max(0,(now-lastFrame)/1000));
    lastFrame=now;

    if(!active)return;

    mixer.update(dt);
    const duration=Math.max(.001,rollClip.duration/CFG.animationSpeed);
    const fraction=clamp(action.time/Math.max(.001,rollClip.duration),0,1);
    progress=dodgeKind==="backward"?1-fraction:fraction;

    // V90: same FBX animation, but the locomotion covers more ground and
    // gets useful displacement sooner. This makes a correctly timed dodge actually
    // escape the attack path instead of only rolling in place.
    const baseCurve=smooth(progress);
    const curve=1-Math.pow(1-baseCurve,1.35);
    const deltaCurve=Math.max(0,curve-lastCurve);
    lastCurve=curve;
    const distance=dodgeKind==="backward"?CFG.backDistance:
      (dodgeKind==="left"||dodgeKind==="right")?CFG.sideDistance:CFG.distance;
    moveDistance(deltaCurve*distance);

    syncBodyAndCamera(args);

    if(dodgeKind==="backward"?action.time<=.001:action.time>=rollClip.duration-.001){
      finishRoll("done");
    }
  };

  // Keyboard: V rolls. This capture listener also prevents conflicting actions
  // from being started while the roll owns the body.
  window.addEventListener("keydown",e=>{
    if(e.code==="KeyV"){
      if(!e.repeat && startRoll()){
        e.preventDefault();
        e.stopImmediatePropagation();
      }
      return;
    }

    if(active && [
      "Space","KeyR","KeyQ","KeyF","KeyE","KeyH","KeyI",
      "ControlLeft","ControlRight","KeyC"
    ].includes(e.code)){
      e.preventDefault();
      e.stopImmediatePropagation();
    }
  },true);

  document.getElementById("c")?.addEventListener("pointerdown",e=>{
    if(active){
      e.preventDefault();
      e.stopImmediatePropagation();
    }
  },true);

  // Mobile/touch dodge button next to Jump.
  let rollBtn=document.getElementById("rollBtn");
  if(!rollBtn){
    rollBtn=document.createElement("button");
    rollBtn.id="rollBtn";
    rollBtn.type="button";
    rollBtn.textContent="Rolar ↻";
    rollBtn.setAttribute("aria-label","Rolar para desviar");
    rollBtn.style.cssText=[
      "pointer-events:auto","position:absolute","right:118px","bottom:28px",
      "width:92px","height:64px","border:1px solid #ffffff55","border-radius:16px",
      "background:#0009","color:white","font:inherit","font-weight:700","cursor:pointer",
      "touch-action:manipulation","z-index:30"
    ].join(";");
    (document.getElementById("jumpBtn")?.parentElement||document.body).appendChild(rollBtn);
  }
  rollBtn.addEventListener("pointerdown",e=>{
    e.preventDefault();
    e.stopPropagation();
    startRoll();
  });

  const hint=document.getElementById("hint");
  if(hint && !/V: rolar/i.test(hint.textContent||"")){
    hint.textContent+=(hint.textContent?" • ":"")+"V: rolar";
  }
  if(hint && !/V \+ A/i.test(hint.textContent||"")){
    hint.textContent+=" • V + A/D: cambalhota lateral • V + S: cambalhota para trás";
  }

  window.gameRoll={
    version:"V168L-PC-DIRECTIONAL-DODGE",
    sourceFile:SOURCE,
    config:CFG,
    start:startRoll,
    cancel:()=>finishRoll("cancel"),
    get active(){return active;},
    get invulnerable(){return isInvulnerable();},
    get progress(){return progress;},
    get direction(){return {x:rollDirX,z:rollDirZ,yaw:rollYaw,facingYaw:rollFacingYaw,kind:dodgeKind};},
    get kind(){return dodgeKind;},
    get duration(){return rollClip.duration/CFG.animationSpeed;},
    get trackCount(){return rollClip.tracks.length;}
  };

  if(status){
    status.textContent=`V168L PC • V+W frontal preservado • V+A/D lateral • V+S traseiro • ${rollClip.tracks.length} tracks • i-frames ${Math.round(CFG.iframeStart*100)}–${Math.round(CFG.iframeEnd*100)}%`;
  }
})().catch(err=>{
  console.error("V90 rolamento longo POV:",err);
  const status=document.getElementById("status");
  if(status)status.textContent="Falha no rolamento: "+String(err?.message||err);
});
